def components(grid):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q, cells = deque([(r, c)]), []
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                            seen.add((ny,nx)); q.append((ny,nx))
            result.append((color, cells))
    return result


def norm(cells):
    mr, mc = min(r for r,c in cells), min(c for r,c in cells)
    return frozenset((r-mr,c-mc) for r,c in cells)


def variants(shape):
    result = set()
    for reflect in (False, True):
        for _turns in range(4):
            pts = [(r, -c if reflect else c) for r,c in shape]
            for _ in range(_turns):
                pts = [(c,-r) for r,c in pts]
            mr, mc = min(r for r,c in pts), min(c for r,c in pts)
            result.add(frozenset((r-mr,c-mc) for r,c in pts))
    return result


def transform(grid):
    out = [row[:] for row in grid]
    comps = components(grid)
    keys = set()
    for color, cells in comps:
        if color == 8:
            keys.add(norm(cells))
    # Mark non-8 components whose silhouette and orientation exactly match an 8 object.
    for color, cells in comps:
        if color != 8 and norm(cells) in keys:
            for r,c in cells:
                out[r][c] = 8
    return out

