    """Return 4-connected non-background components as (color, cells)."""
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            result.append((color, cells))
    return result


def shape(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return frozenset((r - min_r, c - min_c) for r, c in cells)


def transform(grid):
    out = [row[:] for row in grid]
    objs = components(grid)
    # Each non-1 colored object labels the matching silhouette. Recolor only
    # the matching 1 objects, keeping the labeled exemplars unchanged.
    labels = {}
    for color, cells in objs:
        if color != 1:
            labels.setdefault(shape(cells), color)
    for color, cells in objs:
        if color == 1:
            new_color = labels.get(shape(cells))
            if new_color is not None:
                for r, c in cells:
                    out[r][c] = new_color
    return out


